settings.custom_liquid:
{{ 'relax.css' | asset_url | stylesheet_tag }}
<div class="relax-payments">
  <span class="relax-payments__label"><span class="relax-icon">{% render 'relax-icon', icon: 'lock' %}</span> Paiement 100 % sécurisé — cryptage SSL</span>
  <div class="relax-payments__icons">
    {%- assign relax_payment_types = 'visa,master,cartes_bancaires,american_express,paypal,apple_pay,google_pay' | split: ',' -%}
    {%- for type in relax_payment_types -%}
      {{ type | payment_type_svg_tag: class: 'icon icon--full-color' }}
    {%- endfor -%}
  </div>
</div>
